// Tab names EXACTLY as Excel stores them. ZZ Client P dropped 7 Oct 2026.
// The trailing spaces on 'ZZ Client B' and 'Others' were removed on 28 Sep 2026.
// A rename here means that tab fails to read (the run will error), so keep
// this in step with the workbook - or swap to a worksheet lookup by ID.
const sheets = ['ZZ Client A', 'ZZ Client B', 'ZZ Client C', 'ZZ Client D', 'Others'];

return sheets.map(function (name) {
  return { json: { sheetName: name } };
});

function colToNum(s) {
  let n = 0;
  for (let i = 0; i < s.length; i++) { n = n * 26 + (s.charCodeAt(i) - 64); }
  return n;
}

function numToCol(n) {
  let s = '';
  while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); }
  return s;
}

function norm(s) {
  return String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, '');
}

const out = [];

for (const item of $input.all()) {
  const res = item.json;
  const address = String(res.address || '');
  const values = res.values || [];

  if (!values.length || !address) { continue; }

  const sheetName = address.indexOf('!') >= 0 ? address.split('!')[0].replace(/^'|'$/g, '') : '';
  const ref = address.indexOf('!') >= 0 ? address.split('!')[1] : address;
  const start = ref.split(':')[0];
  const m = start.match(/([A-Z]+)(\d+)/);
  if (!m) { continue; }

  const startColNum = colToNum(m[1]);
  const startRow = parseInt(m[2], 10);

  const headers = (values[0] || []).map(function (h) { return String(h == null ? '' : h).trim(); });

  const cols = {};
  const byNorm = {};
  headers.forEach(function (h, j) {
    if (h) {
      const letter = numToCol(startColNum + j);
      cols[h] = letter;
      byNorm[norm(h)] = { header: h, letter: letter };
    }
  });

  function findCol(aliases) {
    for (const a of aliases) {
      const hit = byNorm[norm(a)];
      if (hit) { return hit; }
    }
    return null;
  }

  // Column G is still labelled 'Add to Fergus?' in the workbook - left alone on purpose
  // so CBS staff keep using the dropdown they know. Aliases cover a later rename.
  const flagCol = findCol(['Add to Fergus?', 'Add to Fergus', 'Add to ServiceM8?', 'Add to ServiceM8', 'Create Job?']);
  const statusCol = findCol(['Fergus Status', 'ServiceM8 Status', 'Job Status', 'Fergus Result', 'Result']);
  const jobNoCol = findCol(['ServiceM8 Job No', 'Fergus Job No', 'Fergus Job Number', 'Job No (System)']);
  const linkCol = findCol(['Link to job', 'Job Link', 'ServiceM8 Link', 'Fergus Link']);
  const jobNumberCol = findCol(['Job Number', 'Job No', 'Job Ref']);

  if (!flagCol || !statusCol) { continue; }

  for (let i = 1; i < values.length; i++) {
    const row = {};
    headers.forEach(function (h, j) { if (h) { row[h] = values[i][j]; } });

    row._sheetName = sheetName;
    row._sheetKey = sheetName.trim();
    row._rowNumber = startRow + i;
    row._flagCol = flagCol.letter;
    row._statusCol = statusCol.letter;
    row._jobNoCol = jobNoCol ? jobNoCol.letter : null;
    row._linkCol = linkCol ? linkCol.letter : null;
    row._flag = String(row[flagCol.header] == null ? '' : row[flagCol.header]).trim();
    row._status = String(row[statusCol.header] == null ? '' : row[statusCol.header]).trim();
    row._jobNumber = jobNumberCol ? String(row[jobNumberCol.header] == null ? '' : row[jobNumberCol.header]).trim() : '';

    out.push({ json: row });
  }
}

return out;

// Tabs don't share a schema - ZZ Client B calls it 'Reference' where ZZ Client A says
// 'Job Number', and ZZ Client C / Others say 'Client' where ZZ Client A says 'Site'.
// Resolve by alias rather than by one literal header name.
function pick(row, aliases) {
  for (const a of aliases) {
    const v = row[a];
    if (v !== undefined && v !== null && String(v).trim() !== '') {
      return String(v).trim();
    }
  }
  return '';
}

const JOB_NUMBER_ALIASES = ['Job Number', 'Job Number ', 'Reference', 'Job No', 'Job Ref'];
const SITE_ALIASES = ['Site', 'Client'];
const AREA_ALIASES = ['Area'];
const DESC_ALIASES = ['Description'];
const ORIGINATOR_ALIASES = ['Originator', 'Originator '];

// Keys are '<tab>||<site or client cell>', tab name trimmed.
// UUIDs come from the 'CBS - ServiceM8 Client Lookup' workflow.
const MAP = {
  'ZZ Client A||ZZ Client A - Site 1': {
    companyUuid: '01a0d8de-53ff-79fe-9530-912d0415ee4b',
    jobAddress: '1 Sample Road, Sampletown E, London, ZZ99 3ZZ',
    siteContact: 'ZZ Client Contact A'
  },
  'ZZ Client A||ZZ Client A - Site 3': {
    companyUuid: '01a0d8df-bd2e-79fe-9530-b74e1d90811b',
    jobAddress: '2 Sample Street, Sampletown F, Greater London ZZ99 4ZZ',
    siteContact: 'ZZ Client Contact F'
  },
  'ZZ Client A||ZZ Client A - Site 2': {
    companyUuid: '01a0d8e0-4c53-79fe-9530-80609ba07c4b',
    jobAddress: 'Sample Drive, Blakelands, Sampletown A ZZ99 6ZZ',
    siteContact: 'ZZ Client Contact D'
  },
  'ZZ Client B||ZZ Client B Site 3': {
    companyUuid: '01a0e790-57fa-79fe-9530-faa1ce75766b',
    jobAddress: '',
    siteContact: ''
  },
  'ZZ Client B||ZZ Client B Site 1': {
    companyUuid: '01a0e790-1ea1-79fe-9530-7a71fca26d1b',
    jobAddress: '',
    siteContact: ''
  },
  'ZZ Client B||ZZ Client B Site 2': {
    companyUuid: '01a0e78f-aafe-79fe-9530-389f343ce6ab',
    jobAddress: '',
    siteContact: ''
  }
};

// Fallback for tabs where the tab itself identifies the client.
const SHEET_DEFAULTS = {
  'ZZ Client C': {
    companyUuid: '01a115b7-6176-79fe-9531-6e8aec63a0eb',
    jobAddress: 'ZZ Client C, Sample Avenue, Sampletown B, Ashford, Kent, ZZ99 2ZZ',
    siteContact: 'ZZ Client Contact G'
  }
};

const out = [];

for (const item of $input.all()) {
  const row = item.json;
  const sheetName = row._sheetName || '';
  const sheetKey = row._sheetKey || sheetName.trim();

  const jobNumber = pick(row, JOB_NUMBER_ALIASES);
  const site = pick(row, SITE_ALIASES);
  const area = pick(row, AREA_ALIASES);
  const description = pick(row, DESC_ALIASES);
  const originator = pick(row, ORIGINATOR_ALIASES);

  const base = {
    jobNumber: jobNumber,
    sheetName: sheetName,
    rowNumber: row._rowNumber,
    statusCol: row._statusCol,
    jobNoCol: row._jobNoCol,
    linkCol: row._linkCol
  };

  const missing = [];
  if (!jobNumber) { missing.push('Job Number'); }
  if (!site) { missing.push('Site'); }
  if (!area) { missing.push('Area'); }
  if (!description) { missing.push('Description'); }

  if (missing.length) {
    out.push({ json: Object.assign({}, base, { outcome: 'blocked', statusValue: 'Missing info: ' + missing.join(', ') }) });
    continue;
  }

  const key = sheetKey + '||' + site;
  const match = MAP[key] || SHEET_DEFAULTS[sheetKey];

  if (!match) {
    out.push({ json: Object.assign({}, base, { outcome: 'blocked', statusValue: 'Not mapped yet: ' + key }) });
    continue;
  }

  if (!match.companyUuid) {
    out.push({ json: Object.assign({}, base, { outcome: 'blocked', statusValue: 'No ServiceM8 client for ' + site + ' - create it, then add the UUID to the map' }) });
    continue;
  }

  // ServiceM8 has no separate job title field, so the job card headline is
  // the first line of job_description: '<sheet job number> <description>'.
  // Then Area and Raised by only (Site and Source dropped 19 Oct 2026).
  let fullDescription = jobNumber + ' ' + description;
  const details = [];
  if (area) { details.push('Area: ' + area); }
  if (originator) { details.push('Raised by: ' + originator); }
  if (details.length) { fullDescription += '\n\n' + details.join('\n'); }

  out.push({
    json: Object.assign({}, base, {
      outcome: 'ok',
      companyUuid: match.companyUuid,
      jobAddress: match.jobAddress || site,
      siteContact: match.siteContact || '',
      originator: originator,
      jobDescription: fullDescription,
      purchaseOrderNumber: jobNumber
    })
  });
}

return out;

const out = [];

$input.all().forEach(function (item) {
  const j = item.json;

  if (j.statusCol) {
    out.push({ json: { sheetName: j.sheetName, address: j.statusCol + j.rowNumber, field: 'values', value: j.statusValue } });
  }
});

return out;

// ServiceM8's documented deep link to a job card.
const JOB_URL = 'https://go.servicem8.com/openjob/';

const sources = $('Validate and Map Client').all().filter(function (r) {
  return r.json.outcome === 'ok';
});

const out = [];

$input.all().forEach(function (item, i) {
  const job = item.json;
  const source = (sources[i] && sources[i].json) || {};
  const row = source.rowNumber;
  const sheet = source.sheetName;

  // generated_job_id is ServiceM8's own job number, separate from CBS's sheet number.
  const jobNo = job.generated_job_id || '';
  const uuid = job.uuid;

  if (source.statusCol) {
    out.push({ json: { sheetName: sheet, address: source.statusCol + row, field: 'values', value: 'Created' } });
  }
  if (source.jobNoCol) {
    out.push({ json: { sheetName: sheet, address: source.jobNoCol + row, field: 'values', value: String(jobNo) } });
  }
  if (source.linkCol) {
    const label = jobNo ? String(jobNo) : 'Open job';
    out.push({ json: { sheetName: sheet, address: source.linkCol + row, field: 'formulas', value: '=HYPERLINK("' + JOB_URL + uuid + '","' + label + '")' } });
  }
});

return out;

function norm(s) {
  return String(s == null ? '' : s).toLowerCase().replace(/[^a-z]/g, '');
}

const sources = $('Validate and Map Client').all().filter(function (r) {
  return r.json.outcome === 'ok';
});

const out = [];

$input.all().forEach(function (item, i) {
  const job = item.json;
  const s = (sources[i] && sources[i].json) || {};

  if (!s.originator) { return; }
  // No known default contact for this site yet - nothing to compare against,
  // so stay quiet rather than noting every job.
  if (!s.siteContact) { return; }
  if (norm(s.originator) === norm(s.siteContact)) { return; }

  out.push({
    json: {
      jobUuid: job.uuid,
      note: 'Check job contact: raised by ' + s.originator + ', but the site default contact is ' + s.siteContact + '. Update the contact on this job if needed. (Sheet row ' + s.rowNumber + ')'
    }
  });
});

return out;

